import type { registerBones } from 'boneyard-js/react';

type BonesMap = Parameters<typeof registerBones>[0];

// Generated by `pnpm bones:capture`: one `<name>.bones.json` per named skeleton, captured from the
// Storybook stories titled `Bones/…`. Never edit the JSON by hand.
const modules = import.meta.glob<BonesMap[string]>('./*.bones.json', { eager: true, import: 'default' });

export const bones: BonesMap = Object.fromEntries(
  Object.entries(modules).map(([path, data]) => [path.replace(/^\.\//, '').replace(/\.bones\.json$/, ''), data]),
);
